import React, { useEffect, useState, useRef } from "react";
import api from "../services/api";
import { Link } from "react-router-dom";
import * as d3 from "d3";

export default function Dashboard() {
  const [summary, setSummary] = useState(null);
  const [budgetSummary, setBudgetSummary] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState("");
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [budgetAmount, setBudgetAmount] = useState("");
  const [budgetMonth, setBudgetMonth] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  });

  const budgetChartRef = useRef();
  const categoryChartRef = useRef();
  const trendChartRef = useRef();

  useEffect(() => {
    loadAll();
  }, []);

  useEffect(() => {
    if (budgetSummary) renderBudgetChart();
  }, [budgetSummary]);

  useEffect(() => {
    if (transactions.length > 0) {
      renderCategoryChart();
      renderTrendChart();
    }
  }, [transactions]);

  const loadAll = async () => {
    setIsLoading(true);
    try {
      const [summaryData, budgetData, txData] = await Promise.all([
        api.get("/summary/"),
        api.get("/budget-summary/"),
        api.get("/transactions/"),
      ]);
      setSummary(summaryData);
      setBudgetSummary(budgetData);
      const txList = Array.isArray(txData) ? txData : txData.results || [];
      setTransactions(txList);
    } catch {
      setErrorMsg("Failed to load dashboard data.");
    } finally {
      setIsLoading(false);
    }
  };

  const performLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };

  const handleSetBudget = async (e) => {
    e.preventDefault();
    try {
      const [year, month] = budgetMonth.split("-");
      await api.post("/budgets/", {
        month: parseInt(month),
        year: parseInt(year),
        amount: parseFloat(budgetAmount),
      });
      setShowBudgetForm(false);
      setBudgetAmount("");
      loadAll();
    } catch {
      setErrorMsg("Failed to set budget.");
    }
  };

  const renderBudgetChart = () => {
    const budget = parseFloat(budgetSummary.budget_amount) || 0;
    const spent = parseFloat(budgetSummary.total_spent) || 0;

    const data = [
      { label: "Budget", value: budget, color: "#22c55e" },
      { label: "Spent", value: spent, color: "#dc2626" },
    ];

    const w = 400, h = 250, pad = { top: 20, right: 20, bottom: 40, left: 60 };
    d3.select(budgetChartRef.current).selectAll("*").remove();

    const svg = d3.select(budgetChartRef.current).append("svg").attr("width", w).attr("height", h);
    const x = d3.scaleBand().domain(data.map((d) => d.label)).range([pad.left, w - pad.right]).padding(0.4);
    const y = d3.scaleLinear().domain([0, d3.max(data, (d) => d.value) * 1.2 || 100]).nice().range([h - pad.bottom, pad.top]);

    const tooltip = d3.select(budgetChartRef.current).append("div")
      .style("position", "absolute").style("background", "#1f2937").style("color", "#f9fafb")
      .style("padding", "8px 12px").style("border-radius", "6px").style("font-size", "13px")
      .style("pointer-events", "none").style("opacity", 0);

    svg.append("g").selectAll("rect").data(data).join("rect")
      .attr("fill", (d) => d.color).attr("x", (d) => x(d.label))
      .attr("y", h - pad.bottom).attr("height", 0).attr("width", x.bandwidth()).attr("rx", 4)
      .on("mouseenter", function (event, d) {
        d3.select(this).style("opacity", 0.75);
        tooltip.style("opacity", 1).html(`<strong>${d.label}</strong><br/>$${d.value.toFixed(2)}`);
      })
      .on("mousemove", function (event) {
        tooltip.style("left", event.pageX + 12 + "px").style("top", event.pageY - 28 + "px");
      })
      .on("mouseleave", function () {
        d3.select(this).style("opacity", 1);
        tooltip.style("opacity", 0);
      })
      .transition().duration(900)
      .attr("y", (d) => y(d.value))
      .attr("height", (d) => y(0) - y(d.value));

    svg.append("g").selectAll("text").data(data).join("text")
      .attr("x", (d) => x(d.label) + x.bandwidth() / 2)
      .attr("text-anchor", "middle").style("font-size", "12px").style("font-weight", "600").style("fill", "#374151")
      .transition().duration(900)
      .attr("y", (d) => y(d.value) - 6)
      .text((d) => `$${d.value.toFixed(0)}`);

    svg.append("g").attr("transform", `translate(0,${h - pad.bottom})`).call(d3.axisBottom(x))
      .selectAll("text").style("font-size", "12px");

    svg.append("g").attr("transform", `translate(${pad.left},0)`)
      .call(d3.axisLeft(y).ticks(5).tickFormat((v) => `$${v}`))
      .selectAll("text").style("font-size", "11px");
  };

  const renderCategoryChart = () => {
    const catTotals = transactions
      .filter((t) => t.type === "expense")
      .reduce((acc, t) => {
        const cat = t.category_name || t.category || "Other";
        acc[cat] = (acc[cat] || 0) + parseFloat(t.amount);
        return acc;
      }, {});

    const pieData = Object.entries(catTotals).map(([name, total]) => ({ name, total }));
    if (pieData.length === 0) return;

    const w = 400, h = 340, r = Math.min(w, h - 60) / 2;
    d3.select(categoryChartRef.current).selectAll("*").remove();

    const svg = d3.select(categoryChartRef.current).append("svg").attr("width", w).attr("height", h);
    const g = svg.append("g").attr("transform", `translate(${w / 2},${h / 2 - 20})`);
    const colors = d3.scaleOrdinal(d3.schemePastel1);
    const pie = d3.pie().value((d) => d.total).sort(null);
    const arc = d3.arc().innerRadius(r * 0.52).outerRadius(r);
    const arcHover = d3.arc().innerRadius(r * 0.52).outerRadius(r * 1.1);

    const tooltip = d3.select(categoryChartRef.current).append("div")
      .style("position", "absolute").style("background", "#1f2937").style("color", "#f9fafb")
      .style("padding", "8px 12px").style("border-radius", "6px").style("font-size", "13px")
      .style("pointer-events", "none").style("opacity", 0);

    const total = d3.sum(pieData, (d) => d.total);

    g.selectAll("path").data(pie(pieData)).join("path")
      .attr("d", arc)
      .attr("fill", (d) => colors(d.data.name))
      .attr("stroke", "#fff").style("stroke-width", "2.5px").style("opacity", 0)
      .on("mouseenter", function (event, d) {
        d3.select(this).transition().duration(200).attr("d", arcHover).style("opacity", 1);
        const pct = ((d.data.total / total) * 100).toFixed(1);
        tooltip.style("opacity", 1).html(`<strong>${d.data.name}</strong><br/>$${d.data.total.toFixed(2)}<br/>${pct}%`);
      })
      .on("mousemove", function (event) {
        tooltip.style("left", event.pageX + 12 + "px").style("top", event.pageY - 28 + "px");
      })
      .on("mouseleave", function () {
        d3.select(this).transition().duration(200).attr("d", arc).style("opacity", 0.9);
        tooltip.style("opacity", 0);
      })
      .transition().duration(1000).style("opacity", 0.9)
      .attrTween("d", function (d) {
        const i = d3.interpolate({ startAngle: 0, endAngle: 0 }, d);
        return (t) => arc(i(t));
      });

    const legend = svg.append("g").attr("transform", `translate(10,${h - 45})`);
    pieData.forEach((d, i) => {
      const row = legend.append("g").attr("transform", `translate(${(i % 3) * 125},${Math.floor(i / 3) * 20})`);
      row.append("rect").attr("width", 12).attr("height", 12).attr("fill", colors(d.name)).attr("rx", 2);
      row.append("text").attr("x", 17).attr("y", 10).style("font-size", "11px").style("fill", "#374151")
        .text(d.name.length > 10 ? d.name.slice(0, 10) + "…" : d.name);
    });
  };

  const renderTrendChart = () => {
    const byDay = transactions.reduce((acc, t) => {
      const day = t.date ? t.date.split("T")[0] : "";
      if (!day) return acc;
      if (!acc[day]) acc[day] = { date: day, income: 0, expense: 0 };
      if (t.type === "income") acc[day].income += parseFloat(t.amount);
      else acc[day].expense += parseFloat(t.amount);
      return acc;
    }, {});

    const trendData = Object.values(byDay).sort((a, b) => new Date(a.date) - new Date(b.date)).slice(-30);
    if (trendData.length === 0) return;

    const w = 600, h = 240, pad = { top: 20, right: 80, bottom: 40, left: 55 };
    d3.select(trendChartRef.current).selectAll("*").remove();

    const svg = d3.select(trendChartRef.current).append("svg").attr("width", w).attr("height", h);
    const xScale = d3.scaleTime().domain(d3.extent(trendData, (d) => new Date(d.date))).range([pad.left, w - pad.right]);
    const yMax = d3.max(trendData, (d) => Math.max(d.income, d.expense)) * 1.1 || 10;
    const yScale = d3.scaleLinear().domain([0, yMax]).nice().range([h - pad.bottom, pad.top]);

    const lineIncome = d3.line().x((d) => xScale(new Date(d.date))).y((d) => yScale(d.income)).curve(d3.curveMonotoneX);
    const lineExpense = d3.line().x((d) => xScale(new Date(d.date))).y((d) => yScale(d.expense)).curve(d3.curveMonotoneX);

    const drawLine = (pathData, color) => {
      const p = svg.append("path").datum(trendData).attr("fill", "none").attr("stroke", color).attr("stroke-width", 2.5).attr("d", pathData);
      const len = p.node().getTotalLength();
      p.attr("stroke-dasharray", `${len} ${len}`).attr("stroke-dashoffset", len).transition().duration(1400).attr("stroke-dashoffset", 0);
    };

    drawLine(lineIncome, "#22c55e");
    drawLine(lineExpense, "#dc2626");

    svg.append("g").attr("transform", `translate(0,${h - pad.bottom})`)
      .call(d3.axisBottom(xScale).ticks(5).tickFormat(d3.timeFormat("%b %d")))
      .selectAll("text").style("font-size", "10px").attr("transform", "rotate(-30)").style("text-anchor", "end");

    svg.append("g").attr("transform", `translate(${pad.left},0)`)
      .call(d3.axisLeft(yScale).ticks(5).tickFormat((v) => `$${v}`))
      .selectAll("text").style("font-size", "11px");

    const leg = svg.append("g").attr("transform", `translate(${w - pad.right + 8},${pad.top})`);
    leg.append("line").attr("x2", 18).attr("stroke", "#22c55e").attr("stroke-width", 2.5);
    leg.append("text").attr("x", 22).attr("y", 4).style("font-size", "11px").text("Income");
    leg.append("line").attr("y1", 18).attr("y2", 18).attr("x2", 18).attr("stroke", "#dc2626").attr("stroke-width", 2.5);
    leg.append("text").attr("x", 22).attr("y", 22).style("font-size", "11px").text("Expense");
  };

  if (isLoading) return <p style={{ textAlign: "center", marginTop: 60 }}>Loading...</p>;

  return (
    <div style={{ maxWidth: 820, margin: "40px auto", padding: "0 16px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <div style={{ display: "flex", gap: 16 }}>
          <Link to="/" style={{ textDecoration: "none", color: "#5563DE", fontWeight: 600 }}>Dashboard</Link>
          <Link to="/transactions" style={{ textDecoration: "none", color: "#5563DE", fontWeight: 600 }}>Transactions</Link>
        </div>
        <button onClick={performLogout} style={{ padding: "6px 14px", cursor: "pointer", borderRadius: 6, border: "1px solid #ccc", background: "#fff" }}>Logout</button>
      </div>

      <h2 style={{ marginBottom: 4 }}>Dashboard</h2>
      {errorMsg && <p style={{ color: "red" }}>{errorMsg}</p>}

      {summary && (
        <div style={{ display: "flex", gap: 16, marginBottom: 28, flexWrap: "wrap" }}>
          {[
            { label: "Total Income", value: summary.total_income, color: "#22c55e" },
            { label: "Total Expenses", value: summary.total_expenses, color: "#dc2626" },
            { label: "Balance", value: summary.balance, color: "#5563DE" },
          ].map((card) => (
            <div key={card.label} style={{ flex: 1, minWidth: 160, padding: "16px 20px", borderRadius: 10, border: "1px solid #e5e7eb", background: "#fafafa" }}>
              <p style={{ margin: 0, fontSize: 13, color: "#6b7280" }}>{card.label}</p>
              <p style={{ margin: "6px 0 0", fontSize: 22, fontWeight: 700, color: card.color }}>
                ${parseFloat(card.value || 0).toFixed(2)}
              </p>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginBottom: 28, border: "1px solid #e5e7eb", borderRadius: 10, padding: 20, background: "#fafafa" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <h3 style={{ margin: 0 }}>Budget vs Expenses</h3>
          <button
            onClick={() => setShowBudgetForm(!showBudgetForm)}
            style={{ padding: "6px 14px", cursor: "pointer", borderRadius: 6, border: "1px solid #5563DE", color: "#5563DE", background: "#fff" }}
          >
            {budgetSummary?.budget_amount > 0 ? "Update Budget" : "Set Budget"}
          </button>
        </div>

        {showBudgetForm && (
          <form onSubmit={handleSetBudget} style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16, alignItems: "center" }}>
            <input
              type="month"
              value={budgetMonth}
              onChange={(e) => setBudgetMonth(e.target.value)}
              required
              style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }}
            />
            <input
              type="number"
              placeholder="Budget amount"
              value={budgetAmount}
              onChange={(e) => setBudgetAmount(e.target.value)}
              required
              min="0"
              step="0.01"
              style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc", width: 160 }}
            />
            <button type="submit" style={{ padding: "6px 14px", background: "#5563DE", color: "#fff", border: "none", borderRadius: 5, cursor: "pointer" }}>Save</button>
            <button type="button" onClick={() => setShowBudgetForm(false)} style={{ padding: "6px 14px", border: "1px solid #ccc", borderRadius: 5, cursor: "pointer", background: "#fff" }}>Cancel</button>
          </form>
        )}

        {budgetSummary && (
          <div>
            <div style={{ display: "flex", gap: 24, marginBottom: 12, flexWrap: "wrap", fontSize: 14 }}>
              <span><strong>Budget:</strong> ${parseFloat(budgetSummary.budget_amount || 0).toFixed(2)}</span>
              <span><strong>Spent:</strong> ${parseFloat(budgetSummary.total_spent || 0).toFixed(2)}</span>
              <span><strong>Remaining:</strong> ${parseFloat(budgetSummary.remaining || 0).toFixed(2)}</span>
            </div>
            <div ref={budgetChartRef} style={{ position: "relative" }}></div>
          </div>
        )}
      </div>

      <div style={{ marginBottom: 28, border: "1px solid #e5e7eb", borderRadius: 10, padding: 20, background: "#fafafa" }}>
        <h3 style={{ marginTop: 0, marginBottom: 16 }}>Expenses by Category</h3>
        <div ref={categoryChartRef} style={{ position: "relative" }}></div>
        {transactions.filter((t) => t.type === "expense").length === 0 && (
          <p style={{ color: "#9ca3af", fontSize: 14 }}>No expense data to display.</p>
        )}
      </div>

      <div style={{ marginBottom: 28, border: "1px solid #e5e7eb", borderRadius: 10, padding: 20, background: "#fafafa", overflowX: "auto" }}>
        <h3 style={{ marginTop: 0, marginBottom: 16 }}>Income vs Expenses – Last 30 Days</h3>
        <div ref={trendChartRef} style={{ position: "relative" }}></div>
        {transactions.length === 0 && (
          <p style={{ color: "#9ca3af", fontSize: 14 }}>No transaction data to display.</p>
        )}
      </div>

      <div style={{ marginBottom: 40 }}>
        <h3>Recent Transactions</h3>
        {transactions.length === 0 ? (
          <p style={{ color: "#9ca3af" }}>No transactions found.</p>
        ) : (
          <table width="100%" style={{ borderCollapse: "collapse", fontSize: 14 }}>
            <thead>
              <tr style={{ background: "#f3f4f6" }}>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Date</th>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Category</th>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Type</th>
                <th style={{ padding: "10px 8px", textAlign: "right", borderBottom: "1px solid #e5e7eb" }}>Amount</th>
              </tr>
            </thead>
            <tbody>
              {transactions.slice(0, 8).map((t) => (
                <tr key={t.id} style={{ borderBottom: "1px solid #f3f4f6" }}>
                  <td style={{ padding: "8px" }}>{t.date ? new Date(t.date).toLocaleDateString() : "—"}</td>
                  <td style={{ padding: "8px" }}>{t.category_name || t.category || "—"}</td>
                  <td style={{ padding: "8px", textTransform: "capitalize" }}>{t.type}</td>
                  <td style={{ padding: "8px", textAlign: "right", color: t.type === "income" ? "#22c55e" : "#dc2626", fontWeight: 600 }}>
                    ${parseFloat(t.amount).toFixed(2)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
