import React, { useState, useEffect, useCallback } from "react";
import { Link } from "react-router-dom";
import api from "../services/api";
import "../styles/transactions.css";

export default function Transactions() {
  const [transactions, setTransactions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const PAGE_SIZE = 10;

  const [form, setForm] = useState({
    type: "expense",
    category: "",
    amount: "",
    description: "",
    date: new Date().toISOString().split("T")[0],
  });

  const [filters, setFilters] = useState({
    type: "",
    category: "",
    start_date: "",
    end_date: "",
    min_amount: "",
    max_amount: "",
  });

  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({
    type: "expense",
    category: "",
    amount: "",
    description: "",
    date: new Date().toISOString().split("T")[0],
  });

  const buildQuery = useCallback(
    (page) => {
      const params = new URLSearchParams({ page, page_size: PAGE_SIZE });
      if (filters.type) params.append("type", filters.type);
      if (filters.category) params.append("category", filters.category);
      if (filters.start_date) params.append("start_date", filters.start_date);
      if (filters.end_date) params.append("end_date", filters.end_date);
      if (filters.min_amount) params.append("min_amount", filters.min_amount);
      if (filters.max_amount) params.append("max_amount", filters.max_amount);
      return params.toString();
    },
    [filters]
  );

  const fetchTransactions = useCallback(
    async (page = 1) => {
      setLoading(true);
      setError("");
      try {
        const data = await api.get(`/transactions/?${buildQuery(page)}`);
        const results = Array.isArray(data) ? data : data.results || [];
        const count = data.count || results.length;
        setTransactions(results);
        setTotalCount(count);
        setTotalPages(Math.ceil(count / PAGE_SIZE) || 1);
        setCurrentPage(page);
      } catch {
        setError("Failed to load transactions.");
      } finally {
        setLoading(false);
      }
    },
    [buildQuery]
  );

  const fetchCategories = async () => {
    try {
      const data = await api.get("/categories/");
      const cats = Array.isArray(data) ? data : data.results || [];
      setCategories(cats);
    } catch {
      setCategories([]);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    fetchTransactions(1);
  }, [filters]);

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((prev) => ({ ...prev, [name]: value }));
  };

  const resetFilters = () => {
    setFilters({ type: "", category: "", start_date: "", end_date: "", min_amount: "", max_amount: "" });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const payload = {
        type: form.type,
        amount: parseFloat(form.amount),
        description: form.description,
        date: form.date,
      };
      if (form.category) payload.category = parseInt(form.category) || form.category;
      await api.post("/transactions/", payload);
      setForm({ type: "expense", category: "", amount: "", description: "", date: new Date().toISOString().split("T")[0] });
      fetchTransactions(1);
    } catch (err) {
      setError("Failed to add transaction.");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this transaction?")) return;
    try {
      await api.delete(`/transactions/${id}/`);
      fetchTransactions(currentPage);
    } catch {
      setError("Failed to delete transaction.");
    }
  };

  const startEdit = (t) => {
    setEditingId(t.id);
    setEditForm({
      type: t.type,
      category: t.category || "",
      amount: t.amount,
      description: t.description || "",
      date: t.date ? t.date.split("T")[0] : "",
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditForm({ type: "expense", category: "", amount: "", description: "", date: new Date().toISOString().split("T")[0] });
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const payload = {
        type: editForm.type,
        amount: parseFloat(editForm.amount),
        description: editForm.description,
        date: editForm.date,
      };
      if (editForm.category) payload.category = parseInt(editForm.category) || editForm.category;
      await api.put(`/transactions/${editingId}/`, payload);
      cancelEdit();
      fetchTransactions(currentPage);
    } catch {
      setError("Failed to update transaction.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };

  const getCategoryLabel = (t) => t.category_name || t.category || "—";

  return (
    <div style={{ maxWidth: 900, margin: "40px auto", padding: "0 16px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <div style={{ display: "flex", gap: 16 }}>
          <Link to="/" style={{ textDecoration: "none", color: "#5563DE", fontWeight: 600 }}>Dashboard</Link>
          <Link to="/transactions" style={{ textDecoration: "none", color: "#5563DE", fontWeight: 600 }}>Transactions</Link>
        </div>
        <button onClick={handleLogout} style={{ padding: "6px 14px", cursor: "pointer", borderRadius: 6, border: "1px solid #ccc", background: "#fff" }}>Logout</button>
      </div>

      <h2 style={{ marginBottom: 16 }}>Transactions</h2>
      {error && <p style={{ color: "red", marginBottom: 12 }}>{error}</p>}

      <div style={{ marginBottom: 24, padding: 16, border: "1px solid #e5e7eb", borderRadius: 10, background: "#fafafa" }}>
        <h3 style={{ marginTop: 0, marginBottom: 12, fontSize: 15 }}>Add Transaction</h3>
        <form onSubmit={handleSubmit} style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "flex-end" }}>
          <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}
            style={{ padding: "7px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
            <option value="income">Income</option>
            <option value="expense">Expense</option>
          </select>

          <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}
            style={{ padding: "7px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
            <option value="">Select Category</option>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>

          <input type="date" value={form.date} max={new Date().toISOString().split("T")[0]}
            onChange={(e) => setForm({ ...form, date: e.target.value })}
            style={{ padding: "7px 10px", borderRadius: 5, border: "1px solid #ccc" }} />

          <input type="number" placeholder="Amount" value={form.amount} min="0.01" step="0.01" required
            onChange={(e) => setForm({ ...form, amount: e.target.value })}
            style={{ padding: "7px 10px", borderRadius: 5, border: "1px solid #ccc", width: 110 }} />

          <input placeholder="Description" value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            style={{ padding: "7px 10px", borderRadius: 5, border: "1px solid #ccc", flex: 1, minWidth: 140 }} />

          <button type="submit" style={{ padding: "7px 18px", background: "#5563DE", color: "#fff", border: "none", borderRadius: 5, cursor: "pointer", fontWeight: 600 }}>
            Add
          </button>
        </form>
      </div>

      <div style={{ marginBottom: 20, padding: 16, border: "1px solid #e5e7eb", borderRadius: 10, background: "#fafafa" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <h3 style={{ margin: 0, fontSize: 15 }}>Filter</h3>
          <button onClick={resetFilters} style={{ padding: "5px 12px", background: "#6c757d", color: "#fff", border: "none", borderRadius: 5, cursor: "pointer", fontSize: 13 }}>
            Reset
          </button>
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          <select name="type" value={filters.type} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
            <option value="">All Types</option>
            <option value="income">Income</option>
            <option value="expense">Expense</option>
          </select>

          <select name="category" value={filters.category} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
            <option value="">All Categories</option>
            {categories.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>

          <input type="date" name="start_date" value={filters.start_date} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }} />

          <input type="date" name="end_date" value={filters.end_date} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }} />

          <input type="number" name="min_amount" placeholder="Min $" value={filters.min_amount} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc", width: 90 }} />

          <input type="number" name="max_amount" placeholder="Max $" value={filters.max_amount} onChange={handleFilterChange}
            style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc", width: 90 }} />
        </div>
      </div>

      {loading ? (
        <p style={{ textAlign: "center", color: "#9ca3af" }}>Loading...</p>
      ) : transactions.length === 0 ? (
        <p style={{ textAlign: "center", color: "#9ca3af" }}>No transactions found.</p>
      ) : (
        <>
          <p style={{ fontSize: 13, color: "#6b7280", marginBottom: 8 }}>{totalCount} transaction{totalCount !== 1 ? "s" : ""} found</p>
          <table width="100%" style={{ borderCollapse: "collapse", fontSize: 14 }}>
            <thead>
              <tr style={{ background: "#f3f4f6" }}>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Date</th>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Type</th>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Category</th>
                <th style={{ padding: "10px 8px", textAlign: "right", borderBottom: "1px solid #e5e7eb" }}>Amount</th>
                <th style={{ padding: "10px 8px", textAlign: "left", borderBottom: "1px solid #e5e7eb" }}>Description</th>
                <th style={{ padding: "10px 8px", textAlign: "center", borderBottom: "1px solid #e5e7eb" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {transactions.map((t) =>
                editingId === t.id ? (
                  <tr key={t.id} style={{ background: "#fffbeb" }}>
                    <td colSpan="6" style={{ padding: 12 }}>
                      <form onSubmit={handleUpdate} style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "flex-end" }}>
                        <input type="date" value={editForm.date} onChange={(e) => setEditForm({ ...editForm, date: e.target.value })} required
                          style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }} />
                        <select value={editForm.type} onChange={(e) => setEditForm({ ...editForm, type: e.target.value })}
                          style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
                          <option value="income">Income</option>
                          <option value="expense">Expense</option>
                        </select>
                        <select value={editForm.category} onChange={(e) => setEditForm({ ...editForm, category: e.target.value })}
                          style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc" }}>
                          <option value="">Category</option>
                          {categories.map((c) => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                          ))}
                        </select>
                        <input type="number" placeholder="Amount" value={editForm.amount} min="0.01" step="0.01" required
                          onChange={(e) => setEditForm({ ...editForm, amount: e.target.value })}
                          style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc", width: 100 }} />
                        <input placeholder="Description" value={editForm.description}
                          onChange={(e) => setEditForm({ ...editForm, description: e.target.value })}
                          style={{ padding: "6px 10px", borderRadius: 5, border: "1px solid #ccc", flex: 1, minWidth: 120 }} />
                        <button type="submit" style={{ padding: "6px 14px", background: "#22c55e", color: "#fff", border: "none", borderRadius: 5, cursor: "pointer" }}>Save</button>
                        <button type="button" onClick={cancelEdit} style={{ padding: "6px 14px", background: "#6b7280", color: "#fff", border: "none", borderRadius: 5, cursor: "pointer" }}>Cancel</button>
                      </form>
                    </td>
                  </tr>
                ) : (
                  <tr key={t.id} style={{ borderBottom: "1px solid #f3f4f6" }}>
                    <td style={{ padding: "9px 8px" }}>{t.date ? new Date(t.date).toLocaleDateString() : "—"}</td>
                    <td style={{ padding: "9px 8px", textTransform: "capitalize" }}>{t.type}</td>
                    <td style={{ padding: "9px 8px" }}>{getCategoryLabel(t)}</td>
                    <td style={{ padding: "9px 8px", textAlign: "right", color: t.type === "income" ? "#22c55e" : "#dc2626", fontWeight: 600 }}>
                      ${parseFloat(t.amount).toFixed(2)}
                    </td>
                    <td style={{ padding: "9px 8px", color: "#6b7280" }}>{t.description || "—"}</td>
                    <td style={{ padding: "9px 8px", textAlign: "center" }}>
                      <button onClick={() => startEdit(t)}
                        style={{ marginRight: 6, padding: "4px 10px", background: "#5563DE", color: "#fff", border: "none", borderRadius: 4, cursor: "pointer", fontSize: 12 }}>
                        Edit
                      </button>
                      <button onClick={() => handleDelete(t.id)}
                        style={{ padding: "4px 10px", background: "#dc2626", color: "#fff", border: "none", borderRadius: 4, cursor: "pointer", fontSize: 12 }}>
                        Delete
                      </button>
                    </td>
                  </tr>
                )
              )}
            </tbody>
          </table>

          <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 12, marginTop: 20 }}>
            <button
              onClick={() => fetchTransactions(currentPage - 1)}
              disabled={currentPage === 1}
              style={{ padding: "7px 16px", background: currentPage === 1 ? "#e5e7eb" : "#5563DE", color: currentPage === 1 ? "#9ca3af" : "#fff", border: "none", borderRadius: 5, cursor: currentPage === 1 ? "not-allowed" : "pointer" }}>
              Previous
            </button>
            <span style={{ fontSize: 14, color: "#374151" }}>Page {currentPage} of {totalPages}</span>
            <button
              onClick={() => fetchTransactions(currentPage + 1)}
              disabled={currentPage === totalPages}
              style={{ padding: "7px 16px", background: currentPage === totalPages ? "#e5e7eb" : "#5563DE", color: currentPage === totalPages ? "#9ca3af" : "#fff", border: "none", borderRadius: 5, cursor: currentPage === totalPages ? "not-allowed" : "pointer" }}>
              Next
            </button>
          </div>
        </>
      )}
    </div>
  );
}